"""Author the archive-backed olympiad selection; preserve source provenance."""
from pathlib import Path
import json,hashlib,re
ROOT=Path(__file__).resolve().parents[2]
D=ROOT/'book/source/data';OUT=D/'olympiad-selected.json'
INVENTORY=[json.loads(s)for s in (ROOT/'olympiads/catalog/history/archive-material-inventory-2026-10-25-round5.jsonl').read_text().splitlines()]
SOURCES={};TASKS=[]
def source(key,contest,needle):
 vals=[r for r in INVENTORY if r['contest']==contest and needle in (r.get('path')or'') and r.get('accepted_material')]
 assert len(vals)==1,(key,len(vals))
 r=vals[0];assert hashlib.sha256((ROOT/r['path']).read_bytes()).hexdigest()==r['sha256']
 SOURCES[key]={k:r.get(k)for k in ['contest','source_contest','source_url','source_authority','path','sha256','document_type','solution_bearing']}
 return key
# Explicit compound replacements run before the conservative simple-fraction rule.
# In particular, 2018^2/d must remain a quotient of the whole power.
FRACTIONS={
 '\\sqrt{31}/2':'\\frac{\\sqrt{31}}2',
 '(\\sqrt{31}-1)/4':'\\frac{\\sqrt{31}-1}4',
 '\\sqrt{31}/8':'\\frac{\\sqrt{31}}8',
 '6!/24':'\\frac{6!}{24}',
 '12!/60':'\\frac{12!}{60}',
 '2D/35':'\\frac{2D}{35}',
 '(a+b+c)/2':'\\frac{a+b+c}2',
 'p^2/4':'\\frac{p^2}4',
 '\\pi/3':'\\frac\\pi3',
 'AP/PA_1':'\\frac{AP}{PA_1}',
 'BP/PB_1':'\\frac{BP}{PB_1}',
 'CP/PC_1':'\\frac{CP}{PC_1}',
 '[PBC]/[ABC]':'\\frac{[PBC]}{[ABC]}',
 '[PCA]/[ABC]':'\\frac{[PCA]}{[ABC]}',
 '[PAB]/[ABC]':'\\frac{[PAB]}{[ABC]}',
 'PA_1/AA_1':'\\frac{PA_1}{AA_1}',
 '(1-\\alpha)/\\alpha':'\\frac{1-\\alpha}{\\alpha}',
 '(1-t)/t':'\\frac{1-t}t',
 'AD/AB':'\\frac{AD}{AB}',
 'DB/AB':'\\frac{DB}{AB}',
 '(h_A+h_B+h_C)/6':'\\frac{h_A+h_B+h_C}6',
 '(2X+Y)/3':'\\frac{2X+Y}3',
 'V_{\\rm конус}/V_{\\rm цилиндр}':'\\frac{V_{\\rm конус}}{V_{\\rm цилиндр}}',
 'Rh/(R+l)':'\\frac{Rh}{R+l}',
 '4/(t-1)':'\\frac4{t-1}',
 '(d+2018)/3':'\\frac{d+2018}3',
 '(2018^2/d+2018)/3':'\\frac{\\frac{2018^2}d+2018}3',
 'n!/2':'\\frac{n!}2',
 'm/2^r':'\\frac m{2^r}',
 '(v+Av)/2':'\\frac{v+Av}2',
 '(v-Av)/2':'\\frac{v-Av}2',
 '\\pi/2':'\\frac\\pi2',
 '\\pi/4':'\\frac\\pi4',
 '\\sin(nx)/\\sin x':'\\frac{\\sin(nx)}{\\sin x}',
 'dt/\\ln t':'\\frac{dt}{\\ln t}',
 '2x/\\ln(x^2)':'\\frac{2x}{\\ln(x^2)}',
 '1/\\ln x':'\\frac1{\\ln x}',
 '(x-1)/\\ln x':'\\frac{x-1}{\\ln x}',
 'e^u/u':'\\frac{e^u}u',
 '(x^2-x)/\\ln(x^2)':'\\frac{x^2-x}{\\ln(x^2)}',
 '(2^t-1)/t':'\\frac{2^t-1}t',
 '(-1)^{n-1}/n':'\\frac{(-1)^{n-1}}n',
 '1/(2^k+2j-1)':'\\frac1{2^k+2j-1}',
 '1/(1+t)':'\\frac1{1+t}',
 '(210-12)/7':'\\frac{210-12}7',
 'm/(m+1)':'\\frac m{m+1}',
 '1/(m+1)':'\\frac1{m+1}',
 '7\\alpha/5':'\\frac{7\\alpha}5',
 '5/(2n-15)':'\\frac5{2n-15}',
 '7/(2n-15)':'\\frac7{2n-15}',
 'b/(a+b+c)':'\\frac b{a+b+c}',
 '(a+b)/(a+b+c)':'\\frac{a+b}{a+b+c}',
 'b/(a+b)':'\\frac b{a+b}',
 'b^2/((a+b)(b+c))':'\\frac{b^2}{(a+b)(b+c)}',
 'ab/((a+c)(a+b))':'\\frac{ab}{(a+c)(a+b)}',
 'bc/((a+c)(b+c))':'\\frac{bc}{(a+c)(b+c)}',
 '\\binom42/2^4':'\\frac{\\binom42}{2^4}',
}
def olympiad_math_style(s):
 def one(m):
  text=m[0]
  for a,b in sorted(FRACTIONS.items(),key=lambda v:-len(v[0])):text=text.replace(a,b)
  text=re.sub(r'(?<![\\\w}^])([A-Za-z]|[0-9]+)/([A-Za-z]|[0-9]+)(?![\w{^])',lambda z:r'\frac{'+z[1]+'}{'+z[2]+'}',text)
  assert '/' not in text,('Unformatted fraction',text)
  return text
 return re.sub(r'\\\(.*?\\\)|\\\[.*?\\\]',one,s,flags=re.S)
def add(chapter,key,slug,label,pages,q,answer,solution,hard=True):
 TASKS.append(dict(uid='olympiad.'+slug,chapter=chapter,q=olympiad_math_style(q),answer=olympiad_math_style(answer),solution=olympiad_math_style(solution),advanced=hard,olympiad=dict(source_id=key,label=label,source_pages=pages,statement='faithful Russian mathematical restatement',solution='independent exposition; published solution checked where available')))
def save():
 OUT.write_text(json.dumps(TASKS,ensure_ascii=False,indent=2)+'\n')
 (ROOT/'book/references/olympiad-book-sources.json').write_text(json.dumps(SOURCES,ensure_ascii=False,indent=2)+'\n')
 print('Authored',len(TASKS),'tasks;',len(SOURCES),'verified source documents')
source('mmo-early','mmo','6b2f8bb9aaf1-mmo-35-57.pdf')
for y in [1959,1960,1961,1962,1963,1964,1965]:source(f'imo-{y}','IMO',f'IMO/{y}/problems_en_')
for y in [1989,1991,1992]:source(f'apmo-{y}','APMO',f'APMO/{y}/problems_en_')
source('mos-prob-2023-24','mos_probability','e83fdbce546b-')
# Elementary proofs and induction.
add('c01','mmo-early','mmo.1935.II.B3','ММО, 1935, II тур, серия B, № 3',[11],r'Найди сумму \(1^3+3^3+\cdots+(2n-1)^3\) для \(n\in\mathbb N\) и докажи формулу математической индукцией.',r'\(n^2(2n^2-1)\).',r'При \(n=1\) обе части равны \(1\). Предположим, что сумма первых \(k\) слагаемых равна \(k^2(2k^2-1)\). Прибавим следующий куб \((2k+1)^3\). Раскрытие произведений даёт \[k^2(2k^2-1)+(2k+1)^3=(k+1)^2\bigl(2(k+1)^2-1\bigr).\] Это именно требуемая формула для \(k+1\). Проверены база и переход, поэтому равенство верно для всех натуральных \(n\).',False)
add('c01','mmo-early','mmo.1941.I.78.5','ММО, 1941, I тур, 7–8 классы, № 5',[18],r'Докажи, что произведение четырёх последовательных целых чисел, увеличенное на \(1\), является квадратом целого числа.',r'\(n(n+1)(n+2)(n+3)+1=(n^2+3n+1)^2\).',r'Пусть первое число равно \(n\), и положим \(t=n(n+3)\). Произведение двух средних чисел равно \((n+1)(n+2)=t+2\). Поэтому всё выражение равно \(t(t+2)+1=(t+1)^2\). Число \(t+1\) целое при любом целом \(n\), в том числе отрицательном. Это доказывает утверждение без перебора возможных четвёрок.',False)
# Divisibility.
add('c02','imo-1959','imo.1959.1','IMO, 1959, № 1',[1],r'Докажи несократимость дроби \(\dfrac{21n+4}{14n+3}\) при каждом натуральном \(n\).',r'НОД числителя и знаменателя равен \(1\).',r'Любой общий делитель \(d\) чисел \(21n+4\) и \(14n+3\) делит любую их целочисленную линейную комбинацию. Но \[3(14n+3)-2(21n+4)=1.\] Следовательно, положительный общий делитель может быть только единицей. Значит, числитель и знаменатель взаимно просты, и сокращать дробь нельзя.',False)
add('c02','mmo-early','mmo.1940.I.78.3','ММО, 1940, I тур, 7–8 классы, № 3',[16],r'Сколькими нулями оканчивается десятичная запись \(100!=1\cdot2\cdots100\)?',r'\(24\) нулями.',r'Каждый конечный нуль отвечает множителю \(10=2\cdot5\). Двоек в факториале больше, чем пятёрок, поэтому достаточно сосчитать пятёрки. Среди чисел от \(1\) до \(100\) ровно \(20\) кратных \(5\), каждое даёт одну пятёрку. Четыре кратных \(25\) дают ещё по одной пятёрке. Кратных \(125\) среди множителей нет. Итого показатель пятёрки равен \(20+4=24\); ровно столько же десяток можно выделить из произведения.',False)
# Polynomial identities.
add('c09','mmo-early','mmo.1940.I.78.1','ММО, 1940, I тур, 7–8 классы, № 1',[15],r'Разложи на множители \((b-c)^3+(c-a)^3+(a-b)^3\).',r'\(3(b-c)(c-a)(a-b)\).',r'Обозначим три разности через \(u,v,w\); их сумма равна нулю. Подставив \(w=-u-v\), получаем \[u^3+v^3+(-u-v)^3=-3uv(u+v)=3uvw.\] Возвращение к исходным разностям даёт ответ. Знак множителей важен: замена только одной разности на противоположную изменила бы знак произведения.',False)
add('c09','mmo-early','mmo.1946.I.78.5','ММО, 1946, I тур, 7–8 классы, № 5',[23],r'Докажи, что в произведении \((1-x+x^2-\cdots-x^{99}+x^{100})(1+x+x^2+\cdots+x^{100})\) коэффициенты всех нечётных степеней равны нулю.',r'Произведение является чётным многочленом.',r'Положим \(P(x)=1+x+\cdots+x^{100}\). Первый множитель равен \(P(-x)\), так что весь многочлен \(Q(x)=P(x)P(-x)\) удовлетворяет \(Q(-x)=Q(x)\). Если \(Q(x)=\sum c_kx^k\), сравнение коэффициентов в этом тождестве даёт \((-1)^kc_k=c_k\). Для нечётного \(k\) отсюда \(2c_k=0\), значит, \(c_k=0\).',False)
# Systems and exact real solutions.
add('c11','mmo-early','mmo.1935.II.B1','ММО, 1935, II тур, серия B, № 1',[11],r'Сколько действительных троек удовлетворяет \(x+y=2\), \(xy-z^2=1\)? Найди их.',r'Единственная тройка \((1,1,0)\).',r'Из первого уравнения \((x-y)^2=(x+y)^2-4xy=4-4xy\). Второе даёт \(xy=1+z^2\), поэтому \((x-y)^2+4z^2=0\). Оба слагаемых неотрицательны; они равны нулю одновременно. Значит, \(x=y\), \(z=0\), а сумма \(x+y=2\) даёт \(x=y=1\). Подстановка подтверждает оба уравнения.',False)
add('c11','mmo-early','mmo.1937.I.1','ММО, 1937, I тур, № 1',[13],r'Для действительного \(a\) реши над \(\mathbb R\) систему \[\begin{aligned}x+y+z&=a,\\x^2+y^2+z^2&=a^2,\\x^3+y^3+z^3&=a^3.\end{aligned}\]',r'Все перестановки \((a,0,0)\); при \(a=0\) это одна тройка.',r'Обозначим \(s_2=xy+yz+zx\). Возведение первого равенства в квадрат и сравнение со вторым дают \(s_2=0\). Тождество \(x^3+y^3+z^3=(x+y+z)^3-3(x+y+z)s_2+3xyz\) теперь даёт \(xyz=0\). Пусть, например, \(z=0\). Тогда \(xy=s_2=0\), то есть ещё одна координата равна нулю; оставшаяся равна \(a\). Все такие перестановки действительно подходят.',True)
add('exam-rational','imo-1960','imo.1960.2','IMO, 1960, № 2',[1],r'Реши неравенство \[\frac{4x^2}{(1-\sqrt{1+2x})^2}<2x+9.\]',r'\(x\in[-\tfrac12,0)\cup(0,\tfrac{45}{8})\).',r'ОДЗ: \(x\ge-\tfrac12\), \(x\ne0\). При этих условиях \((1-\sqrt{1+2x})(1+\sqrt{1+2x})=-2x\), поэтому левая часть равна \((1+\sqrt{1+2x})^2\). Раскрывая квадрат, получаем \(2+2x+2\sqrt{1+2x}<2x+9\), то есть \(2\sqrt{1+2x}<7\). Обе части последнего неравенства неотрицательны, поэтому оно равносильно \(1+2x<49/4\), откуда \(x<45/8\). Совместив с ОДЗ, получаем \([-\tfrac12,0)\cup(0,\tfrac{45}{8})\).',True)
add('exam-rational','imo-1962','imo.1962.2','IMO, 1962, № 2',[1],r'Реши неравенство \(\sqrt{3-x}-\sqrt{x+1}>\tfrac12\).',r'\(x\in[-1,\,1-\tfrac{\sqrt{31}}8)\).',r'На ОДЗ \([-1,3]\) разность слева строго убывает: первый корень убывает, второй возрастает. Найдём единственную границу. Если \(u=\sqrt{3-x}\), \(v=\sqrt{x+1}\), то \(u^2+v^2=4\). Равенство \(u-v=1/2\) даёт \(uv=15/8\), \(u+v=\sqrt{31}/2\), откуда \(v=(\sqrt{31}-1)/4\). Следовательно, граничное \(x=v^2-1=1-\sqrt{31}/8\). Строгое неравенство выполняется слева от него; точка \(-1\) допустима.',True)
# Counting.
add('c10','mmo-early','mmo.1935.II.C2','ММО, 1935, II тур, серия C, № 2',[12],r'Сколько существует упорядоченных троек натуральных чисел \((a,b,c)\) с \(a+b+c=n\), где \(n\in\mathbb N\)?',r'\(\binom{n-1}{2}\) при \(n\ge3\); при \(n=1,2\) — \(0\).',r'Запишем \(n\) единиц в ряд. Между ними есть \(n-1\) промежутков. Выбор двух разных промежутков для перегородок разбивает ряд на три непустых последовательных блока; их длины и есть \(a,b,c\). Обратно, любая положительная упорядоченная тройка однозначно задаёт эти перегородки. Поэтому число троек равно числу двухэлементных подмножеств множества из \(n-1\) промежутков. При \(n<3\) три положительных слагаемых невозможны.',False)
add('c10','mmo-early','mmo.1935.II.C1','ММО, 1935, II тур, серия C, № 1',[11],r'Каждую грань куба красят своим цветом, используя шесть разных цветов. Сколько раскрасок получается с точностью до вращений? Реши тот же вопрос для правильного додекаэдра (многогранника с двенадцатью правильными пятиугольными гранями) и двенадцати разных цветов.',r'Для куба \(30\); для додекаэдра \(7\,983\,360\).',r'При фиксированном положении многогранника имеется \(6!\) или \(12!\) назначений цветов. У куба \(6\cdot4=24\) вращения: образ выбранной грани выбирается шестью способами, а её ориентация — четырьмя. У додекаэдра аналогично \(12\cdot5=60\). Нетривиальное вращение не сохраняет раскраску, потому что все цвета различны: сохранив каждую грань, оно обязано сохранить весь многогранник поточечно. Поэтому каждый класс содержит ровно \(24\) или \(60\) назначений. Ответы равны \(6!/24\) и \(12!/60\).',True)
# Progressions: a second source is added below after checking its exact year.
add('c12-progressions','mmo-early','mmo.1935.I.v3.1','ММО, 1935, I тур, вариант 3, № 1',[9],r'Найди две действительные прогрессии, арифметическую и геометрическую, по четыре члена в каждой, если суммы соответствующих членов равны \(27,27,39,87\).',r'Арифметическая: \(24,18,12,6\); геометрическая: \(3,9,27,81\).',r'Пусть суммы имеют вид \(s_j=a+(j-1)d+bq^{j-1}\). Вторые разности последовательности сумм равны \(12\) и \(36\). Для геометрической части это \(b(q-1)^2\) и \(bq(q-1)^2\), поэтому \(q=3\), \(b=3\). Из \(a+b=27\) следует \(a=24\); из \(d+b(q-1)=s_2-s_1=0\) следует \(d=-6\). Случаи \(b=0\) и \(q=1\) исключаются ненулевой второй разностью. Подстановка подтверждает все четыре суммы.',True)
# Modelling.
add('exam-models','mmo-early','mmo.1935.I.v2.1','ММО, 1935, I тур, вариант 2, № 1',[9],r'Поезд при постоянной скорости проходит мимо неподвижного наблюдателя за \(t_1\) секунд, а мост длины \(a\) метров — за \(t_2\) секунд. Найди длину поезда и скорость; укажи условия на данные.',r'\(v=\dfrac a{t_2-t_1}\) м/с, \(L=\dfrac{at_1}{t_2-t_1}\) м; \(a>0\), \(0<t_1<t_2\).',r'При прохождении наблюдателя головная часть поезда смещается на длину всего поезда: \(L=vt_1\). Чтобы поезд целиком прошёл мост, головной части надо пройти \(L+a=vt_2\). Вычитание даёт \(a=v(t_2-t_1)\), откуда находятся \(v\) и \(L\). Для положительной длины моста и положительной скорости необходимо \(t_2>t_1>0\); при этих условиях формулы действительно задают физически допустимый поезд.',False)
add('exam-models','mmo-early','mmo.1940.I.78.2','ММО, 1940, I тур, 7–8 классы, № 2',[16],r'Пароход проходит один и тот же речной путь вниз по течению за \(5\) суток, вверх — за \(7\). Сколько суток понадобится плоту? Скорости парохода относительно воды и течения постоянны.',r'\(35\) суток.',r'Пусть расстояние равно \(D\), собственная скорость парохода \(v\), скорость течения \(u\). Тогда \(v+u=D/5\), \(v-u=D/7\). Вычитая, получаем \(2u=D(1/5-1/7)=2D/35\), то есть \(u=D/35\). Плот движется со скоростью течения, поэтому время \(D/u=35\) суток. Само расстояние знать не требуется: оно сокращается в отношении.',False)
add('exam-models','mmo-early','mmo.1935.I.v1.1','ММО, 1935, I тур, вариант 1, № 1',[9],r'Для положительных \(a,b\) отношение среднего арифметического к среднему геометрическому равно \(25:24\). Найди возможные отношения \(a:b\).',r'\(16:9\) или \(9:16\).',r'Условие имеет вид \(12(a+b)=25\sqrt{ab}\). Положим \(t=\sqrt{a/b}>0\) и разделим на \(b\): \(12(t^2+1)=25t\). Значит, \((3t-4)(4t-3)=0\), откуда \(t=4/3\) либо \(t=3/4\). Отношение \(a/b=t^2\) равно соответственно \(16/9\) либо \(9/16\). Оба значения удовлетворяют исходному равенству, где все величины положительны.',True)
# Arithmetic congruences.
add('c21','mmo-early','mmo.1941.II.78.5','ММО, 1941, II тур, 7–8 классы, № 5',[19],r'Докажи, что для простого \(p>3\) число \(p^2\) даёт остаток \(1\) при делении на \(12\).',r'\(p^2\equiv1\pmod{12}\).',r'Число \(p\) нечётно и не делится на \(3\). Поэтому \(p-1\) и \(p+1\) — два последовательных чётных числа; одно из них делится на \(4\), так что их произведение делится на \(8\), в частности на \(4\). Среди трёх последовательных чисел \(p-1,p,p+1\) одно делится на \(3\); это не \(p\), значит, \(3\mid(p-1)(p+1)\). Взаимная простота \(3\) и \(4\) даёт \(12\mid p^2-1\).',False)
add('c21','mmo-early','mmo.1946.I.78.3','ММО, 1946, I тур, 7–8 классы, № 3',[23],r'Найди четырёхзначное натуральное число, имеющее остаток \(112\) при делении на \(131\) и остаток \(98\) при делении на \(132\).',r'\(1946\).',r'Запишем \(N=131k+112\). По модулю \(132\) это \(-k+112\equiv98\), поэтому \(k\equiv14\pmod{132}\). Следовательно, все целые решения имеют вид \(N=1946+17292t\), \(t\in\mathbb Z\). При \(t\ge1\) число больше \(9999\), при \(t\le-1\) отрицательно. Остаётся \(t=0\), и \(N=1946\). Проверка: \(1946=131\cdot14+112=132\cdot14+98\).',False)
# Inequalities.
add('c17','apmo-1989','apmo.1989.1','APMO, 1989, № 1',[1],r'Пусть \(x_1,\ldots,x_n>0\), \(S=x_1+\cdots+x_n\). Докажи \[\prod_{i=1}^n(1+x_i)\le\sum_{k=0}^n\frac{S^k}{k!}.\]',r'Неравенство верно; равенство возможно только при \(n=1\).',r'Обозначим через \(e_k\) сумму всех произведений по \(k\) разных переменных, \(e_0=1\). При раскрытии произведения слева получается \(\sum_{k=0}^n e_k\). В раскрытии \(S^k\) каждое произведение разных переменных встречается \(k!\) раз; остальные слагаемые неотрицательны. Значит, \(k!e_k\le S^k\), и суммирование доказывает оценку. При \(n\ge2\) для \(k=2\) имеются положительные дополнительные слагаемые \(x_i^2\), поэтому неравенство строго. При \(n=1\) обе части равны \(1+x_1\).',True)
add('c17','apmo-1991','apmo.1991.3','APMO, 1991, № 3',[1],r'Положительные числа \(a_i,b_i\), \(1\le i\le n\), удовлетворяют \(\sum a_i=\sum b_i=S\). Докажи \[\sum_{i=1}^n\frac{a_i^2}{a_i+b_i}\ge\frac S2.\]',r'Равенство достигается ровно при \(a_i=b_i\) для всех \(i\).',r'Для каждого индекса раскрытие квадрата даёт \[\frac{a_i^2}{a_i+b_i}=\frac{a_i+b_i}{4}+\frac{a_i-b_i}{2}+\frac{(a_i-b_i)^2}{4(a_i+b_i)}.\] Суммируем: первая сумма равна \(S/2\), вторая — нулю. Поэтому \[\sum_i\frac{a_i^2}{a_i+b_i}-\frac S2=\frac14\sum_i\frac{(a_i-b_i)^2}{a_i+b_i}\ge0.\] Знаменатели положительны, так что равенство возможно ровно при нулевых числителях, то есть \(a_i=b_i\) для каждого \(i\).',True)
